package cn.local.rainreminder;
import android.content.*;import android.graphics.*;import org.json.*;import java.time.*;import java.text.Normalizer;import java.util.*;import java.util.regex.*;
/** Local recognition of booked laboratory classes; dates require a real semester anchor. */
final class LabSchedule {
 static final String NUMBER="[0-9一二三四五六七八九十廿三十两]+";
 static final Pattern HEADER=Pattern.compile("(20\\d{2})[-—–~至](20\\d{2})[-—–]([12一二])学期第?("+NUMBER+")周(?:星期|周)([一二三四五六日天1-7])");
 static final class Record{String term,title,place,raw;int week,day,first,last;}
 static final class Result{List<Record> records=new ArrayList<>();int incomplete;boolean list;String rawText;}
 static String clean(String s){return Normalizer.normalize(s==null?"":s,Normalizer.Form.NFKC).replaceAll("\\s+","").replace('－','-').replace('—','-').replace('–','-').replace('～','-');}
 static int number(String s){if(s.matches("\\d+"))return Integer.parseInt(s);s=s.replace("两","二");if(s.equals("廿"))return 20;int ten=s.indexOf('十');if(ten>=0){int a=ten==0?1:digit(s.charAt(ten-1)),b=ten==s.length()-1?0:digit(s.charAt(ten+1));return a*10+b;}if(s.startsWith("廿"))return 20+(s.length()>1?digit(s.charAt(1)):0);return s.length()==1?digit(s.charAt(0)):-1;}
 static int digit(char c){return "零一二三四五六七八九".indexOf(c);}
 static String canonicalTerm(String raw){String t=clean(raw);Matcher m=Pattern.compile("(20\\d{2})-(20\\d{2})(?:学年)?(?:-([12])|第?([一二12])学期)").matcher(t);if(!m.find())return "";int y=Integer.parseInt(m.group(1)),z=Integer.parseInt(m.group(2));if(z!=y+1)return "";String semester=m.group(3)==null?m.group(4):m.group(3);return y+"-"+z+"-"+(semester.equals("一")?"1":semester.equals("二")?"2":semester);}
 static boolean looksLike(String raw){String t=clean(raw);return t.contains("学期")&&t.contains("实验")&&t.contains("时间");}
 static Result parse(String raw){String t=clean(raw);Result out=new Result();out.rawText=raw;out.list=looksLike(t);Matcher h=HEADER.matcher(t);List<int[]> positions=new ArrayList<>();List<Record> headers=new ArrayList<>();while(h.find()){Record r=new Record();r.term=canonicalTerm(h.group(1)+"-"+h.group(2)+"-"+h.group(3).replace('一','1').replace('二','2'));r.week=number(h.group(4));r.day="日天".contains(h.group(5))?7:h.group(5).matches("[1-7]")?Integer.parseInt(h.group(5)):number(h.group(5));headers.add(r);positions.add(new int[]{h.start(),h.end()});}
 for(int n=0;n<headers.size();n++){Record r=headers.get(n);String body=t.substring(positions.get(n)[1],n+1<headers.size()?positions.get(n+1)[0]:t.length());r.raw=t.substring(positions.get(n)[0],n+1<headers.size()?positions.get(n+1)[0]:t.length());if(!body.contains("实验项目")&&!body.contains("实验时间"))continue;Matcher title=Pattern.compile("实验项目[:：]?(.+?)实验时间[:：]?").matcher(body),time=Pattern.compile("实验时间[:：]?(上午|下午|晚上|晚间|晚)("+NUMBER+")(?:[-~至]("+NUMBER+"))?节").matcher(body),place=Pattern.compile("实验室[:：]?(.+?)(?:删除|$)").matcher(body);if(r.term.isEmpty()||r.week<1||r.week>40||r.day<1||r.day>7||!title.find()||!time.find()||!place.find()){out.incomplete++;continue;}int first=number(time.group(2)),last=time.group(3)==null?first:number(time.group(3)),offset=time.group(1).equals("上午")?0:time.group(1).equals("下午")?4:8;if(first<1||last<first||last>4){out.incomplete++;continue;}r.title=title.group(1).replaceAll("[<>^]","");r.place=place.group(1).replaceAll("[<>^]","");r.place=r.place.replace("樓","楼").replace("綜","综");Matcher room=Pattern.compile("[A-Za-z]\\d{2,4}").matcher(r.place);if(room.find())r.place=r.place.substring(0,room.end());r.first=first+offset;r.last=last+offset;if(r.title.isEmpty()||r.place.isEmpty()){out.incomplete++;continue;}out.records.add(r);}return out;}
 static Bitmap contrast(Bitmap source){int w=source.getWidth(),h=source.getHeight();int[] pixels=new int[w*h];source.getPixels(pixels,0,w,0,0,w,h);for(int y=0;y<h;y++)for(int x=0;x<w;x++){int color=pixels[y*w+x],gray=(Color.red(color)*30+Color.green(color)*59+Color.blue(color)*11)/100;boolean ink=x>w*.02&&x<w*.98&&gray<210&&LocalOcr.saturation(color)<.30f;pixels[y*w+x]=ink?Color.BLACK:Color.WHITE;}Bitmap out=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);out.setPixels(pixels,0,w,0,0,w,h);return out;}
 static String readLines(PaddleReader reader,Bitmap contrast,int from,int until,LocalOcr.Progress progress)throws Exception{return readLines(reader,contrast,contrast,from,until,progress);}
 static String readLines(PaddleReader reader,Bitmap contrast,Bitmap original,int from,int until,LocalOcr.Progress progress)throws Exception{Bitmap part=Bitmap.createBitmap(contrast,0,from,contrast.getWidth(),until-from);StringBuilder out=new StringBuilder();try{List<Rect> lines=PaddleReader.lines(part);int n=0;for(Rect r:lines){progress.update("识别实验课文字 "+(++n)+" / "+lines.size());List<int[]> chunks=new ArrayList<>();int first=-1,last=-1,gap=Math.max(12,r.height());for(int x=0;x<part.getWidth();x++){boolean ink=false;for(int y=r.top;y<r.bottom&&!ink;y++)ink=Color.red(part.getPixel(x,y))<128;if(ink){if(first<0){first=x;}else if(x-last>gap){chunks.add(new int[]{first,last});first=x;}last=x;}}if(first>=0)chunks.add(new int[]{first,last});for(int[] chunk:chunks){Rect box=new Rect(Math.max(0,chunk[0]-3),from+r.top,Math.min(part.getWidth(),chunk[1]+4),from+r.bottom);Bitmap crop=Bitmap.createBitmap(original,box.left,box.top,box.width(),box.height());PaddleReader.Read text;try{text=reader.line(crop);}finally{if(crop!=original)crop.recycle();}if(!text.text.isEmpty())out.append(text.text);}out.append('\n');}}finally{if(part!=contrast)part.recycle();}return out.toString();}
 static Result read(Context c,Bitmap image,LocalOcr.Progress progress)throws Exception{Bitmap contrast=contrast(image);try(PaddleReader reader=new PaddleReader(c)){int cut=Math.min(image.getHeight(),Math.max(1,Math.round(image.getHeight()*.36f)));for(Rect line:PaddleReader.lines(contrast))if(line.top<cut&&line.bottom>cut){cut=line.bottom;break;}String head=readLines(reader,contrast,image,0,cut,progress);if(!looksLike(head))return null;String rest=cut<image.getHeight()?readLines(reader,contrast,image,cut,image.getHeight(),progress):"";return parse(head+rest);}finally{contrast.recycle();}}
 static boolean validAnchor(String term,LocalDate first){String canonical=canonicalTerm(term);if(canonical.isEmpty()||first==null||first.getDayOfWeek()!=DayOfWeek.MONDAY)return false;int year=Integer.parseInt(canonical.substring(0,4));return canonical.endsWith("-1")?first.getYear()==year&&first.getMonthValue()>=7:first.getYear()==year+1&&first.getMonthValue()<=6;}
 static LocalDate anchor(Context c,String term){String canonical=canonicalTerm(term);Set<LocalDate> found=new HashSet<>();String saved=Agenda.prefs(c).getString("labTermStart_"+canonical,"");if(!saved.isEmpty())try{LocalDate first=LocalDate.parse(saved);if(validAnchor(canonical,first))return first;}catch(Exception ignored){}JSONArray events=Agenda.all(c);for(int n=0;n<events.length();n++){JSONObject e=events.optJSONObject(n);if(e==null||!canonical.equals(canonicalTerm(e.optString("schoolTerm"))))continue;int week=e.optInt("schoolWeek");if(week<1||week>40||e.optLong("start")<=0)continue;LocalDate first=Agenda.weekOf(e.optLong("start")).minusWeeks(week-1);if(validAnchor(canonical,first))found.add(first);}return found.size()==1?found.iterator().next():null;}
 static JSONArray events(Context c,Result result,Map<String,LocalDate> anchors,String periodTimes,int source)throws Exception{List<LocalTime[]> periods=ImportActivity.parseTimes(periodTimes);JSONArray out=new JSONArray();for(Record r:result.records){LocalDate first=anchors.get(r.term);if(!validAnchor(r.term,first))throw new IllegalArgumentException("缺少"+r.term+"学期第1周周一日期");if(r.last>periods.size())throw new IllegalArgumentException("请补全晚课节次时间");LocalDate day=first.plusWeeks(r.week-1).plusDays(r.day-1);long start=day.atTime(periods.get(r.first-1)[0]).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli(),end=day.atTime(periods.get(r.last-1)[1]).atZone(ZoneId.systemDefault()).toInstant().toEpochMilli();JSONObject e=Agenda.create(r.title,r.place,start,end,true);e.put("source","labScreenshot").put("schoolTerm",r.term).put("schoolWeek",r.week).put("periods",r.first+"-"+r.last).put("ocr",r.raw).put("sourceImage",source).put("lead",Agenda.prefs(c).getInt("defaultLead",10)).put("scanLead",Agenda.prefs(c).getInt("defaultScanLead",3));out.put(e);}return out;}
}
